"""Runtime configuration resolution for database access."""

from __future__ import annotations

import os
from pathlib import Path


def database_dsn(environ: dict[str, str] | None = None) -> str:
    """Resolve database configuration by the application contract's precedence."""
    values = os.environ if environ is None else environ
    return values.get("DATABASE_URL") or values.get("DATABASE_PATH") or "data/app.db"


def database_path(environ: dict[str, str] | None = None) -> Path:
    """Return the configured SQLite path when the selected DSN is a filesystem path."""
    return Path(database_dsn(environ))
"""Typed application file boundary."""

from __future__ import annotations

from pathlib import Path


class FileStore:
    """Read generated application assets relative to a known application file."""

    def __init__(self, root: str | Path) -> None:
        self._root = Path(root).resolve()

    def read(self, name: str) -> str:
        return (self._root / name).read_text(encoding="utf-8")
"""Reporting boundary; report values are derived from persisted rows."""

from __future__ import annotations

from typing import Any


def query_report(database: Any, query: str, parameters: tuple[object, ...] = ()) -> list[Any]:
    """Run a declared read through the persistence connection abstraction."""
    return database.query(query, parameters)

